@theme {
  --color-paper: #FAF7F2;
  --color-ink: #1B1522;
  --color-accent: #FF6B2B;
  --color-apricot: #FFE6D2;
  --color-mint: #00D4B2;
  --color-carbon: #2A1E30;
  --color-steel: #8E8294;

  --font-display: var(--font-bricolage), system-ui, -apple-system, sans-serif;
  --font-body: var(--font-inter), system-ui, -apple-system, sans-serif;
  --font-mono: var(--font-jetbrains), ui-monospace, monospace;

  --ease-out: cubic-bezier(0.22, 1, 0.36, 1);
  --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-in-out: cubic-bezier(0.65, 0, 0.35, 1);
  --ease-spring: linear(0, 0.4 9%, 0.86 22%, 1.04 33%, 1.01 46%, 0.995 62%, 1);

  --dur-instant: 90ms;
  --dur-fast: 180ms;
  --dur-base: 420ms;
  --dur-slow: 850ms;
  --dur-hero: 1200ms;

  --reveal-shift: 28px;
  --stagger: 75ms;
}

:root {
  --canvas: #FAF7F2;
  --surface: #FAF7F2;
  --surface-alt: #FFE6D2;
  --surface-nested: color-mix(in srgb, #FAF7F2 90%, #1B1522);

  --text: #1B1522;
  --text-secondary: color-mix(in srgb, #1B1522 75%, transparent);
  --text-muted: #8E8294;
  --text-faint: color-mix(in srgb, #8E8294 65%, transparent);
  --text-on-brand: #FAF7F2;
  --text-on-deep: #FAF7F2;
  --text-on-accent: #FAF7F2;

  --border: color-mix(in srgb, #8E8294 25%, transparent);
  --border-strong: color-mix(in srgb, #8E8294 45%, transparent);
  --divider: color-mix(in srgb, #8E8294 15%, transparent);

  --brand-deep: #1B1522;
  --brand-route: #FF6B2B;
  --brand-route-hover: color-mix(in srgb, #FF6B2B 85%, #1B1522);
  --brand-route-pressed: color-mix(in srgb, #FF6B2B 70%, #1B1522);
  --brand-route-soft: #FFE6D2;
  --accent: #FF6B2B;
  --accent-hover: color-mix(in srgb, #FF6B2B 85%, #1B1522);
  --accent-pressed: color-mix(in srgb, #FF6B2B 70%, #1B1522);
  --accent-soft: #FFE6D2;
  --brand-cyan: #00D4B2;
  --brand-cyan-soft: color-mix(in srgb, #00D4B2 15%, #FAF7F2);

  --success: #00D4B2;
  --success-soft: color-mix(in srgb, #00D4B2 15%, #FAF7F2);
  --success-border: color-mix(in srgb, #00D4B2 35%, transparent);
  --warning: #FF6B2B;
  --warning-highlight: #FF6B2B;
  --warning-soft: #FFE6D2;
  --warning-border: color-mix(in srgb, #FF6B2B 35%, transparent);
  --danger: #FF6B2B;
  --danger-soft: #FFE6D2;
  --danger-border: color-mix(in srgb, #FF6B2B 35%, transparent);
  --neutral-status: #8E8294;
  --neutral-status-soft: color-mix(in srgb, #8E8294 15%, #FAF7F2);
  --neutral-status-border: color-mix(in srgb, #8E8294 30%, transparent);

  --font-roboto-mono: var(--font-jetbrains), ui-monospace, monospace;
  --font-ui: var(--font-inter), system-ui, -apple-system, sans-serif;
  --font-display: var(--font-bricolage), system-ui, -apple-system, sans-serif;

  --shadow-low: 0 1px 3px rgba(27, 21, 34, 0.06);
  --shadow-panel: 0 6px 18px -12px rgba(27, 21, 34, 0.22);
}

/* Base resets & typography */
html {
  background-color: var(--canvas);
  color: var(--text);
  font-family: var(--font-ui);
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
}

body.kn-body {
  margin: 0;
  padding: 0;
  min-height: 100vh;
  background-color: var(--canvas);
  color: var(--text);
  overflow-x: clip;
}

/* Halftone Warm Background Texture */
.landing-warm {
  isolation: isolate;
}

.landing-warm::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  background-image: radial-gradient(circle at center, color-mix(in srgb, var(--accent) 34%, transparent) 1.3px, transparent 1.9px);
  background-size: 14px 14px;
  -webkit-mask-image:
    radial-gradient(ellipse 55% 700px at 100% 0%, black 0%, transparent 72%),
    radial-gradient(ellipse 45% 620px at 0% 46%, black 0%, transparent 72%),
    radial-gradient(ellipse 55% 700px at 100% 100%, black 0%, transparent 72%);
  mask-image:
    radial-gradient(ellipse 55% 700px at 100% 0%, black 0%, transparent 72%),
    radial-gradient(ellipse 45% 620px at 0% 46%, black 0%, transparent 72%),
    radial-gradient(ellipse 55% 700px at 100% 100%, black 0%, transparent 72%);
}

.kn-wrap {
  width: 100%;
  max-width: 1260px;
  margin-left: auto;
  margin-right: auto;
  padding-left: clamp(16px, 4vw, 48px);
  padding-right: clamp(16px, 4vw, 48px);
}


/* ==================================================================
   FLASHLIGHT (CURSOR TRAIL)
   ================================================================== */

/* Orange paint trail for the landing page. Above the sticky nav (z-50) and page content,
   below the cookie notice (z-1000); pointer-events: none so it never blocks a click. */
.flashlightTrail {
  position: fixed;
  inset: 0;
  width: 100vw;
  height: 100vh;
  z-index: 60;
  pointer-events: none;
}

/* Night Route: additive light on dark surfaces. */
:where(html[data-theme="dark"]) .flashlightTrail {
  mix-blend-mode: screen;
}

/* No cursor to follow on touch, and no moving trail for reduced-motion users. */
@media (hover: none), (pointer: coarse), (prefers-reduced-motion: reduce) {
  .flashlightTrail {
    display: none;
  }
}


/* ==================================================================
   JOURNEY (3D BACKGROUND ENGINE STAGE)
   ================================================================== */

/*
 * Delivery journey layers.
 *
 * Stacking (inside the landing root, which is `isolation: isolate`):
 *   stage (fixed, z 0): painted fallback sky, WebGL canvas on top of it
 *   page content: positioned after the stage in DOM order, so it paints above
 *
 * No ancestor of the stage may gain a transform/filter (that would re-parent
 * the fixed layer). Content "plates" frost the scene behind reading areas.
 */

.journeyStage {
  position: fixed;
  inset: 0;
  height: 100lvh;
  z-index: 0;
  pointer-events: none;
  overflow: hidden;
}

.journeyCanvasHost {
  position: absolute;
  inset: 0;
}

.journeyCanvas {
  display: block;
  width: 100%;
  height: 100%;
  opacity: 0;
  transition: opacity 1400ms var(--ease-out, ease-out);
}

:where([data-journey="live"]) .journeyCanvas {
  opacity: 1;
}

/* Painted dawn sky + horizon: shown before WebGL starts, without WebGL,
   and with scripting off. Tuned to the scene's opening colors so the
   crossfade into the canvas is seamless. */
.journeyFallback {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 60% 38% at 78% 64%, rgba(255, 196, 140, 0.55), transparent 70%),
    linear-gradient(to bottom, #FAF7F2 0%, #FFE6D2 45%, #8E8294 61%, #2A1E30 100%);
}

:where(html[data-theme="dark"]) .journeyFallback {
  background:
    radial-gradient(ellipse 50% 30% at 78% 64%, rgba(255, 170, 90, 0.18), transparent 70%),
    linear-gradient(to bottom, #1B1522 0%, #2A1E30 40%, #1B1522 100%);
}

/* Solid footer plate, feathered only at the top. */
.journeyFooterPlate {
  position: relative;
}

.journeyFooterPlate > * {
  position: relative;
}

.journeyFooterPlate::before {
  content: "";
  position: absolute;
  inset: -60px 0 0;
  pointer-events: none;
  background: color-mix(in srgb, var(--canvas) 90%, transparent);
  -webkit-backdrop-filter: blur(12px);
  backdrop-filter: blur(12px);
  -webkit-mask-image: linear-gradient(to bottom, transparent 0, black 60px);
  mask-image: linear-gradient(to bottom, transparent 0, black 60px);
}

.arrival {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  margin-bottom: 16px;
  padding: 6px 12px 6px 9px;
  border: 1px solid var(--border);
  border-radius: 999px;
  background: var(--surface-alt);
  font-family: var(--font-roboto-mono), ui-monospace, monospace;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--text-secondary);
  transition:
    color 400ms var(--ease-out, ease-out),
    border-color 400ms var(--ease-out, ease-out),
    background-color 400ms var(--ease-out, ease-out);
}

.arrivalDot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--accent);
  box-shadow: 0 0 0 4px color-mix(in srgb, var(--accent) 22%, transparent);
  animation: blip 1.6s ease-in-out infinite;
}

.arrival[data-arrived="true"] {
  color: var(--success);
  border-color: var(--success-border);
  background: var(--success-soft);
}

.arrival[data-arrived="true"] .arrivalDot {
  background: var(--success);
  box-shadow: 0 0 0 4px color-mix(in srgb, var(--success) 25%, transparent);
  animation: none;
}

@keyframes blip {
  50% {
    opacity: 0.35;
  }
}

/* ------------------------------------------------------------------ */
/* Nav telemetry                                                       */
/* ------------------------------------------------------------------ */

.telemetry {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.navPill {
  position: absolute;
  top: 50%;
  left: 50%;
  translate: -50% -50%;
  display: none;
  align-items: center;
  gap: 10px;
  padding: 7px 14px 7px 11px;
  border: 1px solid var(--border);
  border-radius: 999px;
  background: color-mix(in srgb, var(--surface) 86%, transparent);
  font-family: var(--font-roboto-mono), ui-monospace, monospace;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--text-secondary);
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
  opacity: 0;
  transition: opacity 600ms var(--ease-out, ease-out);
}

.telemetry[data-live="true"] .navPill {
  opacity: 1;
}

.navPillDot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--accent);
  animation: blip 1.6s ease-in-out infinite;
}

.telemetry[data-arrived="true"] .navPillDot {
  background: var(--success);
  animation: none;
}

.navPillStage {
  color: var(--text);
}

@media (min-width: 1100px) {
  .navPill {
    display: inline-flex;
  }
}

.routeLine {
  position: absolute;
  left: 0;
  right: 0;
  bottom: -1px;
  height: 2px;
  background: transparent;
  opacity: 0;
  transition: opacity 600ms var(--ease-out, ease-out);
}

.telemetry[data-live="true"] .routeLine {
  opacity: 1;
}

.routeFill {
  position: absolute;
  inset: 0;
  background: linear-gradient(90deg, color-mix(in srgb, var(--accent) 40%, transparent), var(--accent));
  transform: scaleX(0);
  transform-origin: left;
}

.routeTick {
  position: absolute;
  top: -2px;
  width: 6px;
  height: 6px;
  margin-left: -3px;
  border-radius: 50%;
  background: var(--canvas);
  border: 1.5px solid var(--accent);
}

.routeTruck {
  position: absolute;
  bottom: 3px;
  left: 0;
  translate: -50% 0;
  color: var(--accent);
  line-height: 0;
}

.routeTruck svg {
  fill: currentColor;
}

/* ------------------------------------------------------------------ */
/* Responsive + motion preferences                                      */
/* ------------------------------------------------------------------ */

@media (prefers-reduced-motion: reduce) {
  .journeyCanvas {
    transition: none;
  }

  .arrivalDot,
  .navPillDot {
    animation: none;
  }
}


/* ==================================================================
   PRESENTATION (PINNED CHAPTER STAGES & INTERACTIVE DEMOS)
   ================================================================== */

/*
 * Landing presentation: five pinned scenes over the 3D journey.
 *
 * Layers: the WebGL world (fixed, behind) -> truck tag / connector (fixed,
 * z 0, painted before the page) -> the presentation stage (in flow, sticky).
 * Each stage is one composed frame; beats inside it cross-fade in place.
 *
 * Without scripting, or on very short screens, stages flow as ordinary
 * sections and every beat is shown (see the end of the file).
 */

html:has(.kn-body) {
  scroll-snap-type: y mandatory;
  scroll-behavior: smooth;
}

.chapter {
  --nav-h: 72px;
  position: relative;
  height: 100svh;
  min-height: 100svh;
  max-height: 100svh;
  scroll-margin-top: 0;
  scroll-snap-align: start;
  scroll-snap-stop: always;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  justify-content: center;
  overflow: hidden;
}

.presentationStage {
  position: relative;
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  padding-top: var(--nav-h);
  box-sizing: border-box;
  overflow: hidden;
}

.frame {
  position: relative;
  height: 100%;
  width: min(1240px, calc(100% - 64px));
  margin-inline: auto;
}

/*
 * Soft legibility wash behind text that sits on the scene. One fixed layer
 * for the whole viewport (see SceneScrim): washes cross-fade between beats
 * instead of ending at a stage's edge.
 */
.sceneScrim {
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
}

.scrim {
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0;
  transition: opacity 900ms var(--ease-in-out);
}

.scrim[data-on="true"] {
  opacity: 1;
}

.scrim[data-scrim="left"] {
  background: radial-gradient(
    ellipse 52% 78% at 14% 54%,
    color-mix(in srgb, var(--canvas) 82%, transparent) 0%,
    color-mix(in srgb, var(--canvas) 52%, transparent) 46%,
    transparent 74%
  );
}

.scrim[data-scrim="left-wide"] {
  background: radial-gradient(
    ellipse 64% 92% at 18% 50%,
    color-mix(in srgb, var(--canvas) 84%, transparent) 0%,
    color-mix(in srgb, var(--canvas) 58%, transparent) 50%,
    transparent 78%
  );
}

.scrim[data-scrim="column-left"] {
  background: linear-gradient(
    90deg,
    color-mix(in srgb, var(--canvas) 84%, transparent) 0%,
    color-mix(in srgb, var(--canvas) 62%, transparent) 30%,
    transparent 52%
  );
}

.scrim[data-scrim="right-top"] {
  background:
    radial-gradient(ellipse 46% 44% at 14% 14%, color-mix(in srgb, var(--canvas) 86%, transparent) 0%, transparent 76%),
    radial-gradient(ellipse 42% 70% at 86% 52%, color-mix(in srgb, var(--canvas) 80%, transparent) 0%, transparent 74%);
}

.scrim[data-scrim="top"] {
  background: radial-gradient(
    ellipse 70% 58% at 50% 20%,
    color-mix(in srgb, var(--canvas) 84%, transparent) 0%,
    color-mix(in srgb, var(--canvas) 50%, transparent) 52%,
    transparent 78%
  );
}

/* ------------------------------------------------------------------ */
/* Type                                                                  */
/* ------------------------------------------------------------------ */

.label {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
  margin: 0;
  font-family: var(--font-roboto-mono), ui-monospace, monospace;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--text-secondary);
}

.labelNum {
  color: var(--accent);
  font-weight: 800;
}

.labelRule {
  width: 26px;
  height: 2px;
  border-radius: 2px;
  background: var(--accent);
}

.labelName {
  color: var(--text);
}

.labelMeta {
  color: var(--text-muted);
  font-weight: 600;
  letter-spacing: 0.08em;
}

.labelMeta::before {
  content: "·";
  margin-right: 10px;
  color: var(--text-muted);
}

.display {
  margin: 20px 0 22px;
  max-width: 11.2ch;
  font-size: clamp(48px, 6.1vw, 92px);
  font-weight: 800;
  line-height: 0.94;
  letter-spacing: -0.052em;
  color: var(--brand-deep);
  text-wrap: balance;
}

.title {
  margin: 14px 0 14px;
  max-width: 14ch;
  font-size: clamp(34px, 3.7vw, 56px);
  font-weight: 800;
  line-height: 0.99;
  letter-spacing: -0.045em;
  color: var(--brand-deep);
  text-wrap: balance;
}

:where(html[data-theme="dark"]) .display,
:where(html[data-theme="dark"]) .title,
:where(html[data-theme="dark"]) .finaleTitle {
  color: var(--text);
}

.lead {
  margin: 0;
  max-width: 40ch;
  font-size: 18px;
  line-height: 1.55;
  color: var(--text-secondary);
}

.beatTitle {
  margin: 0 0 8px;
  font-size: 24px;
  font-weight: 800;
  line-height: 1.12;
  letter-spacing: -0.03em;
  color: var(--text);
}

.beatBody {
  margin: 0 0 18px;
  max-width: 42ch;
  font-size: 15.5px;
  line-height: 1.55;
  color: var(--text-secondary);
}

/* ------------------------------------------------------------------ */
/* Actions                                                               */
/* ------------------------------------------------------------------ */

.actions {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: 30px;
}

.actionsCenter {
  justify-content: center;
}

.primary,
.secondary {
  display: inline-flex;
  min-height: 52px;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 0 24px;
  border-radius: 10px;
  font-size: 15px;
  font-weight: 700;
  text-decoration: none;
  transition:
    transform 160ms var(--ease-out),
    box-shadow 160ms var(--ease-out),
    background-color 160ms var(--ease-out),
    border-color 160ms var(--ease-out);
}

.primary {
  border: 1px solid var(--accent);
  background: var(--accent);
  color: var(--text-on-accent);
  box-shadow: 0 12px 28px -12px color-mix(in srgb, var(--accent) 80%, transparent);
}

.primary:hover {
  transform: translateY(-2px);
  background: var(--accent-hover);
  border-color: var(--accent-hover);
}

.primaryIcon {
  transition: transform 200ms var(--ease-out);
}

.primary:hover .primaryIcon {
  transform: translateX(3px);
}

.secondary {
  border: 1px solid var(--border);
  background: color-mix(in srgb, var(--surface) 82%, transparent);
  -webkit-backdrop-filter: blur(12px);
  backdrop-filter: blur(12px);
  color: var(--text);
}

.secondary:hover {
  transform: translateY(-2px);
  border-color: var(--border-strong);
}

.primary:focus-visible,
.secondary:focus-visible,
.tab:focus-visible,
.railLink:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
}

/* ------------------------------------------------------------------ */
/* Beats                                                                 */
/* ------------------------------------------------------------------ */

.beat {
  opacity: 0;
  transform: translate3d(0, 14px, 0);
  pointer-events: none;
  transition:
    opacity 420ms var(--ease-out),
    transform 560ms var(--ease-out);
}

.beat[data-active="true"] {
  opacity: 1;
  transform: none;
  pointer-events: auto;
}

/* Scrolling back up: beats arrive from above, mirroring the way down. */
:where(html[data-story-dir="up"]) .beat:not([data-active="true"]) {
  transform: translate3d(0, -14px, 0);
}

.beatLines {
  display: grid;
}

.beatLines > * {
  grid-area: 1 / 1;
  margin: 0;
  max-width: 44ch;
  font-size: 17px;
  line-height: 1.55;
  color: var(--text-secondary);
}

/* ------------------------------------------------------------------ */
/* Scenes                                                                */
/* ------------------------------------------------------------------ */

.head {
  display: grid;
}

/* 01: one statement, left third, vertically centered. */
.departCopy {
  position: absolute;
  left: 0;
  top: 50%;
  transform: translateY(-52%);
  max-width: 660px;
}

.cue {
  position: absolute;
  left: 50%;
  bottom: 22px;
  translate: -50% 0;
  display: inline-flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  font-family: var(--font-roboto-mono), ui-monospace, monospace;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--text-secondary);
}

.cue::after {
  content: "";
  width: 1.5px;
  height: 36px;
  border-radius: 2px;
  background: linear-gradient(to bottom, var(--accent), transparent);
  transform-origin: top;
  animation: cue 2.2s var(--ease-in-out) infinite;
}

@keyframes cue {
  0% {
    transform: scaleY(0);
    opacity: 1;
  }
  60% {
    transform: scaleY(1);
    opacity: 1;
  }
  100% {
    transform: scaleY(1);
    opacity: 0;
  }
}

/* 02: headline + the load record stacked on the left, yard on the right. */
.prepareColumn {
  position: absolute;
  left: 0;
  top: 50%;
  transform: translateY(-50%);
  display: grid;
  gap: 26px;
  width: min(500px, 44%);
}

/* 03: header pinned top-left; each record takes its own corner. */
.connectedHead {
  position: absolute;
  left: 0;
  top: 5.5%;
  max-width: 600px;
}

.connectedHead .title {
  max-width: 16ch;
}

.tabs {
  display: flex;
  gap: 8px;
  margin: 6px 0 0;
  padding: 0;
  list-style: none;
}

.tab {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 12px 6px 7px;
  border: 1px solid var(--border);
  border-radius: 999px;
  background: color-mix(in srgb, var(--surface) 70%, transparent);
  font-size: 13px;
  font-weight: 700;
  color: var(--text-secondary);
  text-decoration: none;
  transition:
    background-color 240ms var(--ease-out),
    color 240ms var(--ease-out),
    border-color 240ms var(--ease-out);
}

.tabNum {
  display: grid;
  width: 20px;
  height: 20px;
  place-items: center;
  border-radius: 50%;
  background: var(--surface-alt);
  font-family: var(--font-roboto-mono), ui-monospace, monospace;
  font-size: 11px;
}

.tab[aria-current="step"] {
  border-color: var(--brand-deep);
  background: var(--brand-deep);
  color: #FAF7F2;
}

.tab[aria-current="step"] .tabNum {
  background: var(--accent);
  color: #FAF7F2;
}

:where(html[data-theme="dark"]) .tab[aria-current="step"] {
  border-color: var(--brand-route);
  background: var(--brand-route);
}

.connectedBeats {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.connectedBeats > .beat {
  position: absolute;
  width: min(430px, 40%);
}

.connectedBeats > .beat[data-side="left"] {
  left: 0;
  bottom: 6%;
}

.connectedBeats > .beat[data-side="right"] {
  right: 0;
  top: 30%;
}

/* 04: a large dashboard fills the left 60%, the aerial frames the truck right. */
.workspaceColumn {
  position: absolute;
  left: 0;
  top: 50%;
  transform: translateY(-50%);
  display: grid;
  gap: 20px;
  width: min(780px, 62%);
}

.workspaceColumn .title {
  max-width: 18ch;
}

/* 05: closeout on the left, then the finale centered above the docked truck. */
.arriveBeats {
  position: absolute;
  inset: 0;
}

.closeout {
  position: absolute;
  left: 0;
  top: 50%;
  display: grid;
  gap: 24px;
  width: min(500px, 44%);
  transform: translate3d(0, calc(-50% + 14px), 0);
}

.closeout[data-active="true"] {
  transform: translate3d(0, -50%, 0);
}

:where(html[data-story-dir="up"]) .closeout:not([data-active="true"]) {
  transform: translate3d(0, calc(-50% - 14px), 0);
}

.finale {
  position: absolute;
  left: 50%;
  top: 7%;
  width: min(900px, 100%);
  text-align: center;
  transform: translate3d(-50%, 14px, 0);
}

.finale[data-active="true"] {
  transform: translate3d(-50%, 0, 0);
}

:where(html[data-story-dir="up"]) .finale:not([data-active="true"]) {
  transform: translate3d(-50%, -14px, 0);
}

.finaleTitle {
  margin: 18px auto 16px;
  max-width: 19ch;
  font-size: clamp(38px, 4.6vw, 68px);
  font-weight: 800;
  line-height: 0.98;
  letter-spacing: -0.048em;
  color: var(--brand-deep);
  text-wrap: balance;
}

.finaleLead {
  margin: 0 auto;
  max-width: 48ch;
  font-size: 18px;
  line-height: 1.55;
  color: var(--text-secondary);
}

.finale .actions {
  margin-top: 26px;
}

/* ------------------------------------------------------------------ */
/* Demonstrations                                                        */
/* ------------------------------------------------------------------ */

.card {
  margin: 0;
  padding: 20px 22px 16px;
  border: 1px solid color-mix(in srgb, var(--border) 85%, transparent);
  border-radius: 18px;
  background: color-mix(in srgb, var(--surface) 90%, transparent);
  -webkit-backdrop-filter: blur(18px) saturate(1.2);
  backdrop-filter: blur(18px) saturate(1.2);
  box-shadow:
    0 30px 70px -30px rgba(16, 38, 61, 0.42),
    0 2px 6px rgba(16, 38, 61, 0.06);
  color: var(--text);
  text-align: left;
}

:where(html[data-theme="dark"]) .card {
  box-shadow:
    0 30px 70px -30px rgba(0, 0, 0, 0.7),
    0 2px 6px rgba(0, 0, 0, 0.3);
}

.cardHead {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
}

.kicker {
  display: block;
  font-family: var(--font-roboto-mono), ui-monospace, monospace;
  font-size: 10.5px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--text-muted);
}

.cardTitle {
  display: block;
  margin-top: 3px;
  font-family: var(--font-roboto-mono), ui-monospace, monospace;
  font-size: 22px;
  font-weight: 800;
  letter-spacing: -0.02em;
}

.cardFoot {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 8px 14px;
  margin-top: 14px;
  padding-top: 12px;
  border-top: 1px solid var(--divider, var(--border));
}

.footItem {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  font-size: 12.5px;
  color: var(--text-secondary);
}

.illustrative {
  margin-left: auto;
  font-family: var(--font-roboto-mono), ui-monospace, monospace;
  font-size: 9.5px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  white-space: nowrap;
  color: var(--text-muted);
}

.pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 3px 10px;
  border: 1px solid transparent;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 700;
  white-space: nowrap;
  transition:
    background-color 360ms var(--ease-out),
    color 360ms var(--ease-out),
    border-color 360ms var(--ease-out);
}

.pill[data-tone="ok"] {
  border-color: var(--success-border);
  background: var(--success-soft);
  color: var(--success);
}

.pill[data-tone="warn"] {
  border-color: var(--warning-border);
  background: var(--warning-soft);
  color: var(--warning);
}

.pill[data-tone="info"] {
  border-color: color-mix(in srgb, var(--brand-route) 30%, transparent);
  background: var(--brand-route-soft);
  color: var(--brand-route);
}

.pill[data-tone="muted"] {
  border-color: var(--border);
  background: var(--surface-alt);
  color: var(--text-secondary);
}

.unit {
  display: inline-block;
  padding: 1px 8px;
  border-radius: 6px;
  background: var(--accent);
  font-family: var(--font-roboto-mono), ui-monospace, monospace;
  font-weight: 800;
  color: var(--text-on-accent);
}

.mono {
  font-family: var(--font-roboto-mono), ui-monospace, monospace;
}

.via {
  margin-left: 6px;
  font-size: 12px;
  font-weight: 600;
  color: var(--text-muted);
}

.alignEnd {
  text-align: right;
}

/* Load record */
.lane {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: end;
  gap: 12px;
  margin: 18px 0 14px;
}

.lane strong {
  display: block;
  margin-top: 4px;
  font-size: 17px;
  font-weight: 800;
  letter-spacing: -0.01em;
}

.laneLine {
  display: grid;
  width: 64px;
  height: 22px;
  place-items: center;
  color: var(--accent);
  background: linear-gradient(90deg, transparent, var(--border-strong) 20%, var(--border-strong) 80%, transparent) center / 100% 1.5px no-repeat;
}

.laneLine svg {
  padding: 2px;
  border-radius: 50%;
  background: var(--surface);
}

.assign {
  display: grid;
  gap: 4px;
  margin: 0;
}

.assign > div {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 9px 12px;
  border: 1px solid transparent;
  border-radius: 10px;
}

.assign > div[data-highlight="true"] {
  border-color: color-mix(in srgb, var(--accent) 45%, transparent);
  background: color-mix(in srgb, var(--accent-soft) 80%, transparent);
}

.assign dt {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 14px;
  color: var(--text-secondary);
}

.assign dd {
  margin: 0;
  font-size: 15px;
  font-weight: 700;
}

/* Entity records */
.recordId {
  display: flex;
  align-items: center;
  gap: 12px;
}

.recordIcon {
  display: grid;
  width: 42px;
  height: 42px;
  place-items: center;
  border-radius: 12px;
  background: var(--accent-soft);
  color: var(--accent);
}

.owner {
  margin: 14px 0 4px;
  font-family: var(--font-roboto-mono), ui-monospace, monospace;
  font-size: 10.5px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--text-muted);
}

.docList {
  margin: 0;
  padding: 0;
  list-style: none;
}

.docList li {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 0;
  border-top: 1px solid var(--divider, var(--border));
}

.docName {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  font-size: 14.5px;
  font-weight: 600;
}

.docName svg {
  color: var(--text-muted);
}

/* Command center */
.console {
  padding: 0;
  overflow: hidden;
}

.consoleBar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 16px 20px;
  border-bottom: 1px solid var(--divider, var(--border));
}

.consoleTitle {
  display: block;
  white-space: nowrap;
  font-size: 17px;
  font-weight: 800;
  letter-spacing: -0.02em;
}

.roleSwitch {
  display: inline-flex;
  padding: 3px;
  border: 1px solid var(--border);
  border-radius: 10px;
  background: var(--surface-alt);
}

.roleSwitch button {
  padding: 6px 12px;
  border: 0;
  border-radius: 7px;
  background: transparent;
  font: inherit;
  font-size: 12.5px;
  font-weight: 700;
  color: var(--text-secondary);
  cursor: pointer;
  transition:
    background-color 360ms var(--ease-out),
    color 360ms var(--ease-out);
}

.roleSwitch button:hover {
  color: var(--text);
}

.roleSwitch button:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.roleSwitch button[data-on="true"] {
  background: var(--brand-deep);
  color: #FAF7F2;
  cursor: default;
}

:where(html[data-theme="dark"]) .roleSwitch button[data-on="true"] {
  background: var(--brand-route);
}

.stats {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
  padding: 14px 20px;
}

.stats > div {
  padding: 10px 12px;
  border-radius: 10px;
  background: var(--surface-alt);
}

.stats strong {
  display: flex;
  align-items: center;
  min-height: 30px;
  margin-top: 4px;
  font-family: var(--font-roboto-mono), ui-monospace, monospace;
  font-size: 21px;
  font-weight: 800;
}

.table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13.5px;
}

.table th {
  padding: 9px 12px;
  border-top: 1px solid var(--divider, var(--border));
  border-bottom: 1px solid var(--divider, var(--border));
  background: var(--surface-alt);
  font-family: var(--font-roboto-mono), ui-monospace, monospace;
  font-size: 10.5px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-align: left;
  text-transform: uppercase;
  color: var(--text-muted);
}

.table td {
  padding: 11px 12px;
  border-bottom: 1px solid var(--divider, var(--border));
  white-space: nowrap;
}

.table th:first-child,
.table td:first-child {
  padding-left: 20px;
}

.table th:last-child,
.table td:last-child {
  padding-right: 20px;
}

.table tr[data-focus="true"] td {
  background: color-mix(in srgb, var(--accent-soft) 70%, transparent);
  font-weight: 700;
}

.table tr[data-focus="true"] td:first-child {
  box-shadow: inset 3px 0 0 var(--accent);
}

.num {
  text-align: right !important;
  font-family: var(--font-roboto-mono), ui-monospace, monospace;
}

.locked {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-family: var(--font-roboto-mono), ui-monospace, monospace;
  font-size: 11px;
  font-weight: 600;
  color: var(--text-muted);
  animation: lockIn 420ms var(--ease-out);
}

@keyframes lockIn {
  from {
    opacity: 0;
  }
}

.console .cardFoot {
  margin: 0;
  padding: 11px 20px 13px;
  border-top: 0;
}

/* Closeout */
.steps {
  display: grid;
  margin: 14px 0 0;
  padding: 0;
  list-style: none;
}

.steps li {
  display: grid;
  grid-template-columns: 38px minmax(0, 1fr) auto;
  align-items: center;
  gap: 12px;
  padding: 11px 0;
  border-top: 1px solid var(--divider, var(--border));
}

.stepIcon {
  display: grid;
  width: 38px;
  height: 38px;
  place-items: center;
  border-radius: 50%;
  background: var(--surface-alt);
  color: var(--text-secondary);
}

.stepIcon[data-tone="ok"] {
  background: var(--success-soft);
  color: var(--success);
}

.stepIcon[data-tone="info"] {
  background: var(--brand-route-soft);
  color: var(--brand-route);
}

.stepText strong {
  display: block;
  font-size: 15px;
  font-weight: 700;
}

.stepText span {
  display: block;
  font-size: 13px;
  line-height: 1.4;
  color: var(--text-secondary);
}

/* ------------------------------------------------------------------ */
/* Truck tag, connector, chapter rail                                    */
/* ------------------------------------------------------------------ */

.truckTag {
  position: fixed;
  left: 0;
  top: 0;
  z-index: 0;
  pointer-events: none;
  opacity: 0;
  transition: opacity 320ms var(--ease-out);
  will-change: transform;
}

.truckTag[data-show="true"] {
  opacity: 1;
}

.truckTagInner {
  position: absolute;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 10px;
  border-radius: 8px;
  background: color-mix(in srgb, var(--brand-deep) 92%, transparent);
  box-shadow: 0 10px 24px -10px rgba(0, 0, 0, 0.5);
  font-family: var(--font-roboto-mono), ui-monospace, monospace;
  font-size: 11.5px;
  font-weight: 700;
  letter-spacing: 0.04em;
  white-space: nowrap;
  color: #FAF7F2;
  transform: translate(-50%, calc(-100% - 12px));
}

.truckTagInner::after {
  content: "";
  position: absolute;
  left: 50%;
  top: 100%;
  width: 1.5px;
  height: 12px;
  background: color-mix(in srgb, var(--brand-deep) 70%, transparent);
}

.truckTagUnit {
  padding: 1px 6px;
  border-radius: 4px;
  background: var(--accent);
}

.truckTagStatus {
  color: color-mix(in srgb, #FAF7F2 80%, #1B1522);
}

.connector {
  position: fixed;
  inset: 0;
  z-index: 0;
  width: 100vw;
  height: 100vh;
  pointer-events: none;
  overflow: visible;
  opacity: 0;
  transition: opacity 360ms var(--ease-out);
}

.connector[data-show="true"] {
  opacity: 1;
}

.connector path {
  fill: none;
  stroke: var(--accent);
  stroke-width: 1.6;
  stroke-dasharray: 4 5;
  stroke-linecap: round;
}

.rail {
  position: fixed;
  right: 22px;
  top: 50%;
  z-index: 40;
  display: none;
  translate: 0 -50%;
}

.rail ol {
  display: grid;
  gap: 6px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.railLink {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 10px;
  padding: 5px 0 5px 8px;
  border-radius: 6px;
  font-family: var(--font-roboto-mono), ui-monospace, monospace;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-decoration: none;
  text-transform: uppercase;
  color: var(--text-muted);
}

.railLink::after {
  content: "";
  width: 14px;
  height: 2px;
  border-radius: 2px;
  background: var(--border-strong);
  transition:
    width 300ms var(--ease-out),
    background-color 300ms var(--ease-out);
}

.railName {
  max-width: 0;
  overflow: hidden;
  white-space: nowrap;
  opacity: 0;
  transition:
    max-width 300ms var(--ease-out),
    opacity 300ms var(--ease-out);
}

.railLink:hover .railName,
.railLink:focus-visible .railName {
  max-width: 220px;
  opacity: 1;
}

.railLink[aria-current="step"] {
  color: var(--accent);
}

.railLink[aria-current="step"]::after {
  width: 30px;
  background: var(--accent);
}

@media (min-width: 1100px) {
  .rail {
    display: block;
  }
}

/* ------------------------------------------------------------------ */
/* Shorter laptop screens                                                */
/* ------------------------------------------------------------------ */

@media (max-height: 820px) and (min-width: 661px) {
  .display {
    font-size: clamp(44px, 5.4vw, 78px);
  }

  .title {
    font-size: clamp(30px, 3.2vw, 46px);
  }

  .lead,
  .finaleLead {
    font-size: 16.5px;
  }

  .card {
    padding: 16px 18px 12px;
  }

  .lane {
    margin: 12px 0 10px;
  }

  .assign > div {
    padding: 7px 12px;
  }

  .docList li,
  .steps li {
    padding: 8px 0;
  }

  .stats {
    padding: 10px 20px;
  }

  .table td {
    padding: 8px 12px;
  }

  .beatTitle {
    font-size: 21px;
  }

  .beatBody {
    margin-bottom: 12px;
    font-size: 14.5px;
  }
}

/* ------------------------------------------------------------------ */
/* Tablet                                                                */
/* ------------------------------------------------------------------ */

@media (max-width: 980px) and (min-width: 661px) {
  .prepareColumn,
  .closeout {
    width: min(460px, 56%);
  }

  .workspaceColumn {
    width: 100%;
    top: 4%;
    transform: none;
  }

  .connectedBeats > .beat {
    width: min(420px, 56%);
  }

  .hideNarrow {
    display: none;
  }
}

/* ------------------------------------------------------------------ */
/* Phones: text and demo on top, the truck framed in the lower band      */
/* ------------------------------------------------------------------ */

@media (max-width: 660px) {
  .chapter {
    --nav-h: 64px;
  }

  .frame {
    width: calc(100% - 28px);
  }

  .scrim[data-scrim] {
    background: linear-gradient(
      to bottom,
      color-mix(in srgb, var(--canvas) 86%, transparent) 0%,
      color-mix(in srgb, var(--canvas) 70%, transparent) 50%,
      transparent 72%
    );
  }

  .display {
    margin: 14px 0 14px;
    font-size: clamp(38px, 11vw, 50px);
  }

  .title {
    margin: 10px 0 10px;
    font-size: clamp(28px, 8.2vw, 36px);
  }

  .lead,
  .finaleLead,
  .beatLines > * {
    font-size: 15px;
  }

  .departCopy,
  .prepareColumn,
  .workspaceColumn,
  .closeout {
    top: 18px;
    width: 100%;
    transform: none;
  }

  .closeout,
  .closeout[data-active="true"] {
    transform: none;
  }

  :where(html[data-story-dir="up"]) .closeout:not([data-active="true"]) {
    transform: translate3d(0, -14px, 0);
  }

  .prepareColumn,
  .workspaceColumn,
  .closeout {
    gap: 14px;
  }

  .actions {
    flex-direction: column;
    margin-top: 22px;
  }

  .cue {
    display: none;
  }

  .connectedHead {
    top: 14px;
  }

  .tabs {
    margin-top: 2px;
  }

  .connectedBeats > .beat,
  .connectedBeats > .beat[data-side="left"],
  .connectedBeats > .beat[data-side="right"] {
    top: 176px;
    bottom: auto;
    left: 0;
    right: 0;
    width: 100%;
  }

  .beatTitle {
    font-size: 19px;
  }

  .beatBody {
    margin-bottom: 12px;
    font-size: 14px;
  }

  .finale {
    top: 20px;
  }

  .finaleTitle {
    font-size: clamp(30px, 8.6vw, 38px);
  }

  .card {
    padding: 14px 15px 10px;
    border-radius: 16px;
  }

  /* The console's bar, table and footer carry their own insets. */
  .console {
    padding: 0;
  }

  .cardTitle {
    font-size: 18px;
  }

  .lane {
    margin: 12px 0 8px;
  }

  .lane strong {
    font-size: 15px;
  }

  .laneLine {
    width: 36px;
  }

  .assign > div {
    padding: 6px 10px;
  }

  .docList li,
  .steps li {
    padding: 7px 0;
  }

  .recordIcon {
    width: 36px;
    height: 36px;
  }

  .owner {
    margin-top: 8px;
  }

  /* Wrap rather than push the role switch past the card edge on narrow phones. */
  .consoleBar {
    flex-wrap: wrap;
    gap: 10px;
    padding: 12px 14px;
  }

  .consoleBar > div:first-child {
    flex: 1 1 0%;
  }

  .roleSwitch button {
    padding: 5px 9px;
    font-size: 12px;
  }

  /* The table carries the story on phones; the stat tiles would push the
     truck out of frame. */
  .stats {
    display: none;
  }

  .stats > div {
    padding: 7px 10px;
  }

  .stats strong {
    min-height: 24px;
    font-size: 17px;
  }

  .table {
    font-size: 12.5px;
  }

  .table td,
  .table th {
    padding: 7px 8px;
  }

  .table th:first-child,
  .table td:first-child {
    padding-left: 14px;
  }

  .table th:last-child,
  .table td:last-child {
    padding-right: 14px;
  }

  .hideNarrow,
  .table th:nth-child(2),
  .table td:nth-child(2) {
    display: none;
  }

  .console .cardFoot {
    padding: 8px 14px 10px;
  }

  .steps li {
    grid-template-columns: 32px minmax(0, 1fr) auto;
    gap: 10px;
  }

  .stepIcon {
    width: 32px;
    height: 32px;
  }

  .stepText strong {
    font-size: 14px;
  }

  .stepText span {
    font-size: 12px;
  }

  .footItem {
    font-size: 11.5px;
  }
}

/* ------------------------------------------------------------------ */
/* Motion and scripting fallbacks                                        */
/* ------------------------------------------------------------------ */

@media (prefers-reduced-motion: reduce) {
  .beat,
  .beat[data-active="true"],
  .scrim,
  .truckTag,
  .connector {
    transition: none;
  }

  .beat {
    transform: none;
  }

  .closeout {
    transform: translate3d(0, -50%, 0);
  }

  .finale {
    transform: translate3d(-50%, 0, 0);
  }

  .cue::after,
  .locked {
    animation: none;
  }
}

/*
 * No scripting, reduced motion, or a screen too short to pin a composed frame:
 * every chapter flows as a normal section and every beat is visible in order,
 * so alternate beats (the arrival finale) are never left at opacity 0.
 */
@media (scripting: none), (prefers-reduced-motion: reduce), (max-height: 540px) {
  .chapter {
    height: auto;
  }

  .presentationStage {
    position: relative;
    top: auto;
    height: auto;
    min-height: calc(100svh - var(--nav-h));
    padding: 56px 0 72px;
    overflow: visible;
  }

  .frame {
    height: auto;
  }

  .departCopy,
  .prepareColumn,
  .connectedHead,
  .connectedBeats,
  .connectedBeats > .beat[data-side],
  .workspaceColumn,
  .arriveBeats,
  .closeout,
  .closeout[data-active],
  .finale,
  .finale[data-active] {
    position: relative;
    inset: auto;
    width: auto;
    max-width: 760px;
    transform: none;
  }

  .connectedBeats,
  .arriveBeats {
    display: grid;
    gap: 40px;
    margin-top: 32px;
  }

  .beat,
  :where(html[data-story-dir]) .beat:not([data-active="true"]),
  :where(html[data-story-dir]) .closeout:not([data-active="true"]),
  :where(html[data-story-dir]) .finale:not([data-active="true"]) {
    opacity: 1;
    transform: none;
    pointer-events: auto;
  }

  .beatLines {
    gap: 12px;
  }

  .beatLines > * {
    grid-area: auto;
  }

  /* Flowed, the finale sits over the docked-truck still, so give it a readable plate. */
  .finale {
    margin-inline: auto;
    padding: 28px 32px 36px;
    border: 1px solid var(--border);
    border-radius: 28px;
    background: color-mix(in srgb, var(--surface) 90%, transparent);
    -webkit-backdrop-filter: blur(18px);
    backdrop-filter: blur(18px);
  }
}

